#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]
//! The M1 acceptance tests for the store (brief WP1.3 names, criterion 2), run on the committed
//! fixtures in `fixtures/syntax/` (generated by `folioxide_testkit::fixtures::syntax`).
//!
//! The unit tests in `src/store/tests.rs` with the same names use small inline files; these use
//! the shared fixtures that the oracle suite and the fuzz corpus also use. On top of the named
//! tests, [`every_fixture_opens_resolves_and_decodes`] reads every committed fixture in both
//! strictness modes: each one opens (or fails with its documented error code), and every object
//! resolves and every stream decodes without panicking.
//!
//! The linearized files that qpdf wrote into `fixtures/qpdf/`
//! (`folioxide_testkit::fixtures::qpdf`) check the revision structure of a layout that our own
//! builder does not produce ([`linearized_revisions_end_at_their_own_startxref`]).

use std::sync::Arc;
use std::sync::mpsc;
use std::time::Duration;

use folioxide_syntax::filters::encode_flate;
use folioxide_syntax::{
    DiagnosticKind, ErrorCode, Limits, Object, ObjectId, OpenOptions, Store, StreamData,
    Strictness, XrefKind,
};
use folioxide_testkit::exercise::{exercise, page_count};
use folioxide_testkit::fixtures::{qpdf, syntax};
use folioxide_testkit::{PdfBuilder, XrefOpts};

// ---- helpers ------------------------------------------------------------------------------------

/// The committed bytes of `fixtures/syntax/<name>.pdf`.
fn committed(name: &str) -> Vec<u8> {
    syntax::read_committed(name).unwrap_or_else(|err| {
        panic!("fixtures/syntax/{name}.pdf: {err} (run `cargo xtask fixtures`)")
    })
}

fn options(strictness: Strictness) -> OpenOptions {
    OpenOptions::default().with_strictness(strictness)
}

fn open(name: &str) -> Store {
    Store::open_bytes(committed(name), &OpenOptions::default())
        .unwrap_or_else(|err| panic!("{name}: {err}"))
}

fn open_strict(name: &str) -> folioxide_syntax::Result<Store> {
    Store::open_bytes(committed(name), &options(Strictness::Strict))
}

fn id(num: u32) -> ObjectId {
    ObjectId::new(num, 0)
}

fn ids(nums: &[u32]) -> Vec<ObjectId> {
    nums.iter().copied().map(id).collect()
}

fn kinds(store: &Store) -> Vec<DiagnosticKind> {
    store.diagnostics().iter().map(|d| d.kind).collect()
}

/// The content stream the fixture generators write: one line of `text` at height `y`.
fn content(text: &str, y: u32) -> Vec<u8> {
    format!("BT /F1 24 Tf 72 {y} Td ({text}) Tj ET").into_bytes()
}

/// The decoded data of stream `num`.
fn stream_of(store: &Store, num: u32) -> Vec<u8> {
    let obj = store.resolve(id(num)).unwrap();
    let stream = obj
        .as_stream()
        .unwrap_or_else(|| panic!("{num} is a {}", obj.type_name()));
    let decoded = store.stream_data(stream).unwrap();
    assert!(decoded.is_fully_decoded());
    decoded.data
}

/// The usual document of the fixtures: catalog 1, page tree 2, page 3 (with content stream 4
/// showing `text`), font 5.
fn check_one_page(store: &Store, text: &str) {
    let catalog = store.resolve(store.root_id().unwrap()).unwrap();
    assert!(catalog.as_dict().unwrap().is_type(b"Catalog"));
    assert!(
        store
            .resolve(id(2))
            .unwrap()
            .as_dict()
            .unwrap()
            .is_type(b"Pages")
    );
    assert!(
        store
            .resolve(id(3))
            .unwrap()
            .as_dict()
            .unwrap()
            .is_type(b"Page")
    );
    assert!(
        store
            .resolve(id(5))
            .unwrap()
            .as_dict()
            .unwrap()
            .is_type(b"Font")
    );
    assert_eq!(stream_of(store, 4), content(text, 720));
    assert_eq!(page_count(store), Some(1));
}

fn rfind(bytes: &[u8], needle: &[u8]) -> usize {
    bytes
        .windows(needle.len())
        .rposition(|w| w == needle)
        .unwrap()
}

/// Runs `f` on another thread and fails if it takes longer than `seconds` (a hang is a bug).
fn within(seconds: u64, f: impl FnOnce() + Send + 'static) {
    let (tx, rx) = mpsc::channel();
    let handle = std::thread::spawn(move || {
        f();
        let _ = tx.send(());
    });
    match rx.recv_timeout(Duration::from_secs(seconds)) {
        Ok(()) => handle.join().unwrap(),
        Err(mpsc::RecvTimeoutError::Disconnected) => {
            if let Err(panic) = handle.join() {
                std::panic::resume_unwind(panic);
            }
        }
        Err(mpsc::RecvTimeoutError::Timeout) => panic!("did not finish in {seconds} s"),
    }
}

/// How strict mode treats each fixture: `None` when it opens, otherwise the error code.
/// Lenient mode opens every fixture except the two encrypted ones.
fn strict_open_error(name: &str) -> Option<ErrorCode> {
    match name {
        "xref-subsection-starts-at-1"
        | "xref-offsets-off-by-n"
        | "startxref-off-by-n"
        | "prev-loop"
        | "missing-xref"
        | "missing-xref-with-trailer" => Some(ErrorCode::Xref),
        "junk-before-header" | "objstm-n-too-large" => Some(ErrorCode::Syntax),
        "encrypted" => Some(ErrorCode::PasswordRequired),
        "encrypted-unknown-handler" => Some(ErrorCode::Unsupported),
        _ => None,
    }
}

// ---- every fixture -------------------------------------------------------------------------------

#[test]
fn committed_fixtures_match_the_generators() {
    let all = syntax::all();
    assert_eq!(all.len(), syntax::infos().len());
    for (name, generated) in all {
        assert!(
            committed(name) == generated,
            "fixtures/syntax/{name}.pdf is stale; run `cargo xtask fixtures`"
        );
    }
}

#[test]
fn every_fixture_opens_resolves_and_decodes() {
    for info in syntax::infos() {
        let name = info.name;
        let bytes = committed(name);
        let encrypted = name.starts_with("encrypted");

        // Lenient: everything but the encrypted files opens, and every object is readable.
        let report = exercise(&bytes, &options(Strictness::Lenient));
        assert!(
            report.violations.is_empty(),
            "{name}: {:?}",
            report.violations
        );
        if encrypted {
            assert_eq!(report.open_error, strict_open_error(name), "{name}");
        } else {
            assert_eq!(report.open_error, None, "{name}");
            assert!(report.objects >= 5, "{name}: {report:?}");
            assert_eq!(report.non_null, report.objects, "{name}: null objects");
            assert_eq!(report.resolve_errors, 0, "{name}");
            assert_eq!(report.decode_errors, 0, "{name}");
            assert!(report.streams >= 1, "{name}");
            assert_eq!(report.pages, Some(info.pages), "{name}");
            if info.conforming {
                assert_eq!(report.diagnostics, 0, "{name}");
            }
        }

        // Strict: conforming files open and read without any error.
        assert!(
            !info.conforming || strict_open_error(name).is_none(),
            "{name} is conforming but strict mode refuses it"
        );
        let report = exercise(&bytes, &options(Strictness::Strict));
        assert!(
            report.violations.is_empty(),
            "{name}: {:?}",
            report.violations
        );
        assert_eq!(
            report.open_error,
            strict_open_error(name),
            "{name} (strict)"
        );
        if info.conforming {
            assert_eq!(report.resolve_errors + report.decode_errors, 0, "{name}");
            assert_eq!(report.non_null, report.objects, "{name}");
            assert_eq!(report.pages, Some(info.pages), "{name}");
            assert_eq!(report.diagnostics, 0, "{name}");
        }
    }
}

#[test]
fn store_is_send_sync() {
    fn assert_send_sync<T: Send + Sync + 'static>() {}
    assert_send_sync::<Store>();
    // ... and usable from several threads at once.
    let store = Arc::new(open("objstm-extends"));
    let handles: Vec<_> = (0..4)
        .map(|_| {
            let store = Arc::clone(&store);
            std::thread::spawn(move || {
                store
                    .object_ids()
                    .into_iter()
                    .map(|id| store.resolve(id).unwrap())
                    .collect::<Vec<_>>()
            })
        })
        .collect();
    let results: Vec<_> = handles.into_iter().map(|h| h.join().unwrap()).collect();
    for other in &results[1..] {
        assert!(results[0].iter().zip(other).all(|(a, b)| Arc::ptr_eq(a, b)));
    }
}

// ---- cross-reference tables (trap #3) ------------------------------------------------------------

#[test]
fn xref_table_eol_variants() {
    // The three 20-byte entry endings of §7.5.4, and the 19-byte LF and CR ones that writers
    // produce anyway: all read without a single diagnostic.
    for (name, twenty_bytes) in [
        ("xref-eol-space-lf", true),
        ("xref-eol-space-cr", true),
        ("xref-eol-crlf", true),
        ("xref-eol-lf", false),
        ("xref-eol-cr", false),
    ] {
        let store = open(name);
        check_one_page(&store, name);
        assert_eq!(store.object_ids(), ids(&[1, 2, 3, 4, 5]), "{name}");
        assert!(
            store.diagnostics().is_empty(),
            "{name}: {:?}",
            store.diagnostics()
        );
        assert_eq!(store.revisions()[0].xref_kind, XrefKind::Table);
        if twenty_bytes {
            check_one_page(&open_strict(name).unwrap(), name);
        }
    }
}

#[test]
fn xref_subsection_starts_at_1_repaired() {
    let name = "xref-subsection-starts-at-1";
    let store = open(name);
    check_one_page(&store, name);
    assert_eq!(store.object_ids(), ids(&[1, 2, 3, 4, 5]));
    assert_eq!(kinds(&store), [DiagnosticKind::XrefSubsectionShifted]);
    assert_eq!(open_strict(name).unwrap_err().code(), ErrorCode::Xref);
}

#[test]
fn xref_offsets_off_by_n_repaired() {
    let name = "xref-offsets-off-by-n";
    let store = open(name);
    check_one_page(&store, name);
    // One repair per object, found by the ±64-byte search when the object is first read.
    assert_eq!(kinds(&store), [DiagnosticKind::XrefOffsetRepaired; 5]);
    assert_eq!(open_strict(name).unwrap_err().code(), ErrorCode::Xref);
}

#[test]
fn startxref_off_by_n_repaired() {
    let name = "startxref-off-by-n";
    let bytes = committed(name);
    let store = open(name);
    check_one_page(&store, name);
    assert_eq!(kinds(&store), [DiagnosticKind::XrefOffsetRepaired]);
    // The revision records where the section really is, not what startxref says.
    let xref = rfind(&bytes, b"\nxref") as u64 + 1;
    assert_eq!(store.revisions()[0].startxref, xref);
    assert_eq!(store.revisions()[0].xref_kind, XrefKind::Table);
    assert_eq!(open_strict(name).unwrap_err().code(), ErrorCode::Xref);
}

#[test]
fn prev_loop_detected() {
    let name = "prev-loop";
    let store = open(name);
    assert_eq!(kinds(&store), [DiagnosticKind::XrefLoop]);
    // Both sections are read once; the newer content stream wins.
    assert_eq!(store.revisions().len(), 2);
    check_one_page(&store, "Revision 2");
    assert_eq!(open_strict(name).unwrap_err().code(), ErrorCode::Xref);
}

#[test]
fn junk_before_header() {
    let name = "junk-before-header";
    let bytes = committed(name);
    let store = open(name);
    assert_eq!(store.header_offset(), 118);
    assert_eq!(&bytes[118..123], b"%PDF-");
    assert_eq!(store.version(), (1, 4));
    check_one_page(&store, name);
    assert_eq!(kinds(&store), [DiagnosticKind::HeaderOffset]);
    // Stream ranges are absolute positions in the source, junk included.
    let obj = store.resolve(id(4)).unwrap();
    let StreamData::Source(range) = &obj.as_stream().unwrap().data else {
        panic!("not a source stream");
    };
    assert_eq!(
        &bytes[range.start as usize..range.end as usize],
        content(name, 720)
    );
    assert_eq!(store.revisions()[0].eof_end, bytes.len() as u64);
    assert_eq!(open_strict(name).unwrap_err().code(), ErrorCode::Syntax);
}

#[test]
fn multi_revision_newest_entries_win() {
    let store = open_strict("multi-revision").unwrap();
    let revisions = store.revisions();
    assert_eq!(revisions.len(), 3);
    assert!(revisions.iter().all(|r| r.xref_kind == XrefKind::Table));
    assert!(revisions.windows(2).all(|w| w[0].eof_end < w[1].eof_end));
    assert_eq!(store.trailer(), &revisions[2].trailer);
    // Revision 2 replaced content stream 4; revision 3 replaced the page tree, added page 7
    // with content 8, and freed /Info 6 (generation 1).
    assert_eq!(stream_of(&store, 4), content("Revision 2", 720));
    assert_eq!(stream_of(&store, 8), content("Revision 3, page 2", 720));
    assert_eq!(store.object_ids(), ids(&[1, 2, 3, 4, 5, 7, 8]));
    assert!(store.resolve(id(6)).unwrap().is_null());
    assert!(store.trailer().get(b"Info").is_none());
    assert_eq!(page_count(&store), Some(2));
    assert!(store.diagnostics().is_empty());
}

// ---- cross-reference streams and hybrids (trap #4) ----------------------------------------------

#[test]
fn xref_stream_w0_default() {
    let name = "xref-stream-w0";
    let store = open_strict(name).unwrap();
    check_one_page(&store, name);
    assert_eq!(store.revisions()[0].xref_kind, XrefKind::Stream);
    assert!(store.trailer().is_type(b"XRef"));
    assert_eq!(store.trailer().get_array(b"W").unwrap().len(), 3);
    // The stream lists objects 1-6 (itself included) with type 1 and generation 0 by default.
    assert_eq!(store.object_ids(), ids(&[1, 2, 3, 4, 5, 6]));
    assert!(store.diagnostics().is_empty(), "{:?}", store.diagnostics());
}

#[test]
fn xref_streams_with_predictor_and_prev() {
    let store = open_strict("xref-stream").unwrap();
    check_one_page(&store, "xref-stream");
    assert_eq!(store.revisions()[0].xref_kind, XrefKind::Stream);

    let store = open_strict("xref-stream-incremental").unwrap();
    assert_eq!(store.revisions().len(), 2);
    assert!(
        store
            .revisions()
            .iter()
            .all(|r| r.xref_kind == XrefKind::Stream)
    );
    check_one_page(&store, "Revision 2");
    assert_eq!(store.trailer().get_ref(b"Info"), Some(id(7)));
    assert_eq!(store.object_ids(), ids(&[1, 2, 3, 4, 5, 6, 7, 8]));
    assert!(store.diagnostics().is_empty(), "{:?}", store.diagnostics());
}

#[test]
fn hybrid_xrefstm() {
    let name = "hybrid";
    let store = open_strict(name).unwrap();
    assert_eq!(store.revisions()[0].xref_kind, XrefKind::Hybrid);
    // The catalog 1 and page tree 2 are only in object stream 6, which only the /XRefStm
    // stream lists; the table skips them.
    check_one_page(&store, name);
    assert_eq!(store.object_ids(), ids(&[1, 2, 3, 4, 5, 6, 7]));
    assert!(store.diagnostics().is_empty(), "{:?}", store.diagnostics());

    // With /XRefStm pointing nowhere the table alone cannot find the catalog: lenient mode
    // reports it and recovers the compressed objects by scanning; strict mode refuses.
    let mut broken = committed(name);
    let at = rfind(&broken, b"/XRefStm ") + "/XRefStm ".len();
    broken[at] = b'9';
    let store = Store::open_bytes(broken.clone(), &OpenOptions::default()).unwrap();
    check_one_page(&store, name);
    assert_eq!(
        kinds(&store)[..2],
        [
            DiagnosticKind::XrefMalformed,
            DiagnosticKind::XrefReconstructed
        ]
    );
    let err = Store::open_bytes(broken, &options(Strictness::Strict)).unwrap_err();
    assert_eq!(err.code(), ErrorCode::Xref);
}

// ---- object streams (trap #5) --------------------------------------------------------------------

#[test]
fn objstm_extends_chain() {
    let name = "objstm-extends";
    let store = open_strict(name).unwrap();
    check_one_page(&store, name);
    // 12 /Extends 11 /Extends 10: the catalog is in 12, pages in 11, font and /Info in 10.
    for (container, extends) in [(12, Some(11)), (11, Some(10)), (10, None)] {
        let obj = store.resolve(id(container)).unwrap();
        let dict = &obj.as_stream().unwrap().dict;
        assert!(dict.is_type(b"ObjStm"), "{container}");
        assert_eq!(dict.get_ref(b"Extends"), extends.map(id), "{container}");
    }
    let info = store.resolve(id(7)).unwrap();
    assert_eq!(
        info.as_dict().unwrap().get_str_bytes(b"Title"),
        Some(&b"Extends chain"[..])
    );
    // 6, 8 and 9 are unused.
    assert_eq!(store.object_ids(), ids(&[1, 2, 3, 4, 5, 7, 10, 11, 12, 13]));
    for free in [6, 8, 9] {
        assert!(store.resolve(id(free)).unwrap().is_null());
    }
    assert!(store.diagnostics().is_empty(), "{:?}", store.diagnostics());
    // Compressed objects have generation 0 only.
    assert!(store.resolve(ObjectId::new(1, 1)).unwrap().is_null());
    assert_eq!(kinds(&store), [DiagnosticKind::WrongGeneration]);

    // A loop in /Extends (9 -> 10 -> 9) never hangs.
    within(10, || {
        let store =
            Store::open_bytes(committed("objstm-extends-loop"), &OpenOptions::default()).unwrap();
        check_one_page(&store, "objstm-extends-loop");
        assert_eq!(store.object_ids(), ids(&[1, 2, 3, 4, 5, 9, 10, 11]));
    });
}

#[test]
fn objstm_members_resolve() {
    let store = open_strict("objstm").unwrap();
    check_one_page(&store, "objstm");
    // Content stream 4 is Flate-compressed and outside the object stream.
    let obj = store.resolve(id(4)).unwrap();
    assert!(obj.as_stream().unwrap().dict.get(b"Filter").is_some());
    assert_eq!(store.trailer().get_ref(b"Info"), Some(id(7)));
    assert!(store.resolve(id(7)).unwrap().as_dict().is_some());
}

#[test]
fn objstm_n_too_large() {
    let name = "objstm-n-too-large";
    let store = open(name);
    check_one_page(&store, name);
    assert_eq!(kinds(&store), [DiagnosticKind::ObjectStream]);
    assert_eq!(open_strict(name).unwrap_err().code(), ErrorCode::Syntax);
}

// ---- stream lengths (trap #1) --------------------------------------------------------------------

#[test]
fn stream_length_wrong_recovers() {
    let name = "stream-length-wrong";
    let store = open(name);
    for (num, expected) in [
        (4, content("Length too short", 720)),
        (6, content("Length too long", 690)),
        (7, content("Length missing", 660)),
        (8, content("Flate, Length too long", 630)),
    ] {
        assert_eq!(stream_of(&store, num), expected, "stream {num}");
    }
    assert_eq!(kinds(&store), [DiagnosticKind::StreamLength; 4]);
    // The diagnostics point at the streams.
    assert!(store.diagnostics().iter().all(|d| d.offset.is_some()));

    let strict = open_strict(name).unwrap();
    for num in [4, 6, 7, 8] {
        assert_eq!(
            strict.resolve(id(num)).unwrap_err().code(),
            ErrorCode::Syntax,
            "stream {num}"
        );
    }
}

#[test]
fn length_indirect_cycle() {
    let name = "length-indirect-cycle";
    within(10, move || {
        let store = open(name);
        // A valid indirect /Length (10 0 R, written after the stream) needs no repair.
        assert_eq!(stream_of(&store, 9), content("indirect Length", 660));
        assert!(store.diagnostics().is_empty(), "{:?}", store.diagnostics());
        // /Length 4 0 R (the stream itself) and /Length 7 0 R (7 -> 8 -> 7): delimited by
        // `endstream` instead.
        assert_eq!(
            stream_of(&store, 4),
            content("Length refers to its own stream", 720)
        );
        assert_eq!(
            stream_of(&store, 6),
            content("Length is a reference cycle", 690)
        );
        assert_eq!(kinds(&store), [DiagnosticKind::StreamLength; 2]);
        // Following the cycle itself ends in null.
        assert!(store.deref(&Object::Ref(id(7))).unwrap().is_null());
        assert!(
            kinds(&store).contains(&DiagnosticKind::UnresolvedReference),
            "{:?}",
            kinds(&store)
        );

        let strict = open_strict(name).unwrap();
        assert_eq!(stream_of(&strict, 9), content("indirect Length", 660));
        assert!(strict.resolve(id(4)).is_err());
        assert!(strict.resolve(id(6)).is_err());
    });
}

#[test]
fn flate_bomb_limited() {
    // 16 MiB of zeros, Flate-compressed once (about 16 KB) and twice (a few hundred bytes).
    let plain = vec![0u8; 16 << 20];
    let once = encode_flate(&plain, 9);
    let twice = encode_flate(&once, 9);
    assert!(twice.len() < 1024, "{}", twice.len());
    let mut b = PdfBuilder::new();
    b.header("1.4")
        .obj(1, 0, "<< /Type /Catalog /Pages 2 0 R >>")
        .obj(2, 0, "<< /Type /Pages /Kids [] /Count 0 >>")
        .stream_obj(3, 0, "/Filter /FlateDecode", &once, None)
        .stream_obj(4, 0, "/Filter [/FlateDecode /FlateDecode]", &twice, None);
    b.xref_table(XrefOpts::default());
    b.trailer(format!("/Size {} /Root 1 0 R", b.size()))
        .startxref(None)
        .eof();
    let bytes = b.build();

    let decode = |store: &Store, num: u32| {
        let obj = store.resolve(id(num)).unwrap();
        store.stream_data(obj.as_stream().unwrap())
    };
    // A 1 MiB limit per stream stops both bombs, in both modes.
    let limits = Limits::default().with_max_decoded_stream(1 << 20);
    for strictness in [Strictness::Lenient, Strictness::Strict] {
        let store =
            Store::open_bytes(bytes.clone(), &options(strictness).with_limits(limits)).unwrap();
        for num in [3, 4] {
            let err = decode(&store, num).unwrap_err();
            assert_eq!(err.code(), ErrorCode::LimitExceeded, "{num} {strictness:?}");
        }
        assert!(
            store.total_decoded() <= 2 << 20,
            "{}",
            store.total_decoded()
        );
    }
    // A 20 MiB budget for the whole document allows one of them, not both.
    let limits = Limits::default().with_max_total_decoded(20 << 20);
    let store =
        Store::open_bytes(bytes.clone(), &OpenOptions::default().with_limits(limits)).unwrap();
    assert_eq!(decode(&store, 3).unwrap().data.len(), 16 << 20);
    assert_eq!(
        decode(&store, 4).unwrap_err().code(),
        ErrorCode::LimitExceeded
    );
    // With the default limits the bombs are just large streams.
    let store = Store::open_bytes(bytes, &OpenOptions::default()).unwrap();
    assert!(decode(&store, 4).unwrap().data == plain);
}

#[test]
fn flate_truncated_partial() {
    let name = "flate-truncated";
    let store = open(name);
    let obj = store.resolve(id(4)).unwrap();
    let decoded = store.stream_data(obj.as_stream().unwrap()).unwrap();
    assert!(decoded.truncated);
    assert!(decoded.is_fully_decoded());
    // Most of the 60 lines decode; the cut only loses the tail.
    assert!(
        decoded
            .data
            .starts_with(b"BT /F1 10 Tf 72 760 Td (Line 0 of a truncated stream) Tj ET\n")
    );
    let text = String::from_utf8(decoded.data).unwrap();
    assert!(text.contains("(Line 50 of a truncated stream)"), "{text}");
    assert_eq!(kinds(&store), [DiagnosticKind::FilterTruncated]);

    let strict = open_strict(name).unwrap();
    let obj = strict.resolve(id(4)).unwrap();
    let err = strict.stream_data(obj.as_stream().unwrap()).unwrap_err();
    assert_eq!(err.code(), ErrorCode::Filter);
}

// ---- reconstruction --------------------------------------------------------------------------------

#[test]
fn missing_xref_full_reconstruct() {
    // No xref, no trailer, no startxref: the trailer is rebuilt from the /Type /Catalog object.
    let name = "missing-xref";
    let store = open(name);
    check_one_page(&store, name);
    assert_eq!(
        kinds(&store),
        [
            DiagnosticKind::XrefReconstructed,
            DiagnosticKind::TrailerRebuilt
        ]
    );
    assert_eq!(store.revisions().len(), 1);
    assert_eq!(store.revisions()[0].xref_kind, XrefKind::Reconstructed);
    assert_eq!(&store.revisions()[0].trailer, store.trailer());
    assert_eq!(store.root_id(), Some(id(1)));
    assert_eq!(store.trailer().get_int(b"Size"), Some(6));
    assert_eq!(store.object_ids(), ids(&[1, 2, 3, 4, 5]));
    assert_eq!(open_strict(name).unwrap_err().code(), ErrorCode::Xref);

    // A trailer but no xref section: the trailer found by the scan is used as is.
    let name = "missing-xref-with-trailer";
    let store = open(name);
    check_one_page(&store, name);
    assert_eq!(kinds(&store), [DiagnosticKind::XrefReconstructed]);
    assert_eq!(store.revisions()[0].xref_kind, XrefKind::Reconstructed);
    assert!(store.trailer().get(b"ID").is_some());
    assert_eq!(store.object_ids(), ids(&[1, 2, 3, 4, 5]));
    assert_eq!(open_strict(name).unwrap_err().code(), ErrorCode::Xref);
}

// ---- encryption detection ---------------------------------------------------------------------------

#[test]
fn encrypted_returns_password_required() {
    for strictness in [Strictness::Lenient, Strictness::Strict] {
        let err = Store::open_bytes(committed("encrypted"), &options(strictness)).unwrap_err();
        assert_eq!(err.code(), ErrorCode::PasswordRequired, "{err}");
        let err = Store::open_bytes(committed("encrypted-unknown-handler"), &options(strictness))
            .unwrap_err();
        assert_eq!(err.code(), ErrorCode::Unsupported, "{err}");
    }
}

// ---- linearized files written by qpdf (Annex F) --------------------------------------------------

/// The committed bytes of `fixtures/qpdf/<name>.pdf`.
fn committed_qpdf(name: &str) -> Vec<u8> {
    qpdf::read_committed(name).unwrap_or_else(|err| {
        panic!("fixtures/qpdf/{name}.pdf: {err} (run `tools/fixtures/qpdf.py`)")
    })
}

/// The value of the last `startxref` keyword in `bytes`.
fn last_startxref(bytes: &[u8]) -> u64 {
    let at = rfind(bytes, b"startxref") + b"startxref".len();
    let digits: String = bytes[at..]
        .iter()
        .map(|&b| char::from(b))
        .skip_while(char::is_ascii_whitespace)
        .take_while(char::is_ascii_digit)
        .collect();
    digits.parse().unwrap()
}

/// The object number of the `N G obj` header at `offset` in `bytes`.
fn obj_num_at(bytes: &[u8], offset: usize) -> u32 {
    let text = std::str::from_utf8(&bytes[offset..offset + 16]).unwrap_or_else(|_| {
        panic!("no object header at {offset}");
    });
    let mut words = text.split_ascii_whitespace();
    let num = words.next().unwrap().parse().unwrap();
    assert!(words.next().unwrap().parse::<u16>().is_ok(), "{text:?}");
    assert_eq!(words.next(), Some("obj"), "{text:?}");
    num
}

/// The decoded content of every page, in page order (the page tree of a qpdf fixture is flat).
fn page_contents(store: &Store) -> Vec<Vec<u8>> {
    let catalog = store.resolve(store.root_id().unwrap()).unwrap();
    let pages = store
        .deref(catalog.as_dict().unwrap().get(b"Pages").unwrap())
        .unwrap();
    let kids = pages
        .as_dict()
        .unwrap()
        .get_array(b"Kids")
        .unwrap()
        .to_vec();
    kids.iter()
        .map(|kid| {
            let page = store.deref(kid).unwrap();
            let page = page.as_dict().unwrap();
            assert!(page.is_type(b"Page"));
            stream_of(store, page.get_ref(b"Contents").unwrap().num)
        })
        .collect()
}

#[test]
fn qpdf_fixtures_open_resolve_and_decode() {
    for info in qpdf::infos() {
        let name = info.name;
        let bytes = committed_qpdf(name);
        for strictness in [Strictness::Lenient, Strictness::Strict] {
            let report = exercise(&bytes, &options(strictness));
            assert!(
                report.violations.is_empty(),
                "{name}: {:?}",
                report.violations
            );
            assert_eq!(report.open_error, None, "{name} {strictness:?}");
            assert_eq!(report.non_null, report.objects, "{name}");
            assert_eq!(report.resolve_errors + report.decode_errors, 0, "{name}");
            assert_eq!(report.pages, Some(qpdf::PAGES), "{name}");
            assert_eq!(report.diagnostics, 0, "{name} {strictness:?}");
        }
    }
}

#[test]
fn linearized_revisions_end_at_their_own_startxref() {
    // A linearized file (Annex F) has two cross-reference sections: the first-page section near
    // the start, which the final `startxref` points at (the newest revision, whose /Prev is the
    // main section), and the main section at the end. In the table layout the first-page section
    // is followed by a dummy `startxref 0 %%EOF`. Both revisions end with the file: neither is cut
    // at the dummy %%EOF (`Revision::eof_end`; the synthetic unit test of the same name in
    // `src/store/tests.rs` builds the layout by hand, these files come from qpdf).
    for info in qpdf::infos() {
        let name = info.name;
        let bytes = committed_qpdf(name);
        let len = bytes.len() as u64;
        let store = Store::open_bytes(bytes.clone(), &options(Strictness::Strict))
            .unwrap_or_else(|err| panic!("{name}: {err}"));
        assert!(
            store.diagnostics().is_empty(),
            "{name}: {:?}",
            store.diagnostics()
        );
        assert!(!store.structure_repaired(), "{name}");
        assert_eq!(store.version(), info.version, "{name}");

        let revisions = store.revisions();
        assert_eq!(revisions.len(), 2, "{name}");
        let (main, first_page) = (&revisions[0], &revisions[1]);
        assert!(
            revisions.iter().all(|r| r.xref_kind == info.xref_kind),
            "{name}"
        );
        // The final startxref points at the first-page section, near the start of the file,
        // whose /Prev is the main section at the end.
        assert_eq!(first_page.startxref, last_startxref(&bytes), "{name}");
        assert_eq!(
            first_page.trailer.get_int(b"Prev"),
            Some(main.startxref as i64),
            "{name}"
        );
        assert!(first_page.section_end < main.startxref, "{name}");
        assert_eq!(store.trailer(), &first_page.trailer, "{name}");
        // Both end with the file.
        assert_eq!(first_page.eof_end, len, "{name}");
        assert_eq!(main.eof_end, len, "{name}");
        assert!(main.section_end < len, "{name}");
        if info.xref_kind == XrefKind::Table {
            // The dummy `startxref 0 %%EOF` right after the first-page trailer is not its end.
            let dummy = b"startxref\n0\n%%EOF\n";
            let after = &bytes[first_page.section_end as usize..];
            let at = after
                .windows(dummy.len())
                .position(|w| w == dummy)
                .unwrap_or_else(|| panic!("{name}: no dummy startxref"));
            assert!(at < 16, "{name}: {at}");
            assert!(first_page.eof_end > first_page.section_end + (at + dummy.len()) as u64);
        }

        // The first-page section lists the linearization dictionary and the first page's
        // objects; the main section the rest. Together they are every object.
        let entries = |index: usize| -> Vec<u32> {
            store
                .revision_entries(index)
                .unwrap()
                .into_iter()
                .filter(|(_, entry)| !matches!(entry, folioxide_syntax::XrefEntry::Free { .. }))
                .map(|(num, _)| num)
                .collect()
        };
        let (main_objects, first_objects) = (entries(0), entries(1));
        assert!(
            !main_objects.is_empty() && !first_objects.is_empty(),
            "{name}"
        );
        assert!(
            main_objects.iter().all(|n| !first_objects.contains(n)),
            "{name}: {main_objects:?} {first_objects:?}"
        );
        let mut all: Vec<u32> = main_objects.iter().chain(&first_objects).copied().collect();
        all.sort_unstable();
        assert_eq!(
            all,
            store
                .object_ids()
                .iter()
                .map(|id| id.num)
                .collect::<Vec<_>>(),
            "{name}"
        );

        // The linearization dictionary is the first object in the file, in the first-page
        // section, and describes this file.
        let first_obj = bytes.windows(4).position(|w| w == b"obj\n").unwrap();
        let line_start = bytes[..first_obj]
            .iter()
            .rposition(|&b| b == b'\n')
            .unwrap()
            + 1;
        let num = obj_num_at(&bytes, line_start);
        assert!(first_objects.contains(&num), "{name}: {num}");
        let lin = store.resolve(id(num)).unwrap();
        let lin = lin.as_dict().unwrap();
        assert!(lin.get(b"Linearized").is_some(), "{name}");
        assert_eq!(lin.get_int(b"L"), Some(len as i64), "{name}");
        assert_eq!(lin.get_int(b"N"), Some(i64::from(qpdf::PAGES)), "{name}");
        // The first page (/O) is in the first-page section.
        let first_page_obj = u32::try_from(lin.get_int(b"O").unwrap()).unwrap();
        assert!(first_objects.contains(&first_page_obj), "{name}");
        // The primary hint stream starts exactly at /H's offset (Annex F.2.2, an offset into the
        // file), is in the first-page section, and decodes.
        let hint_at = usize::try_from(lin.get_array(b"H").unwrap()[0].as_int().unwrap()).unwrap();
        let hint_num = obj_num_at(&bytes, hint_at);
        assert!(first_objects.contains(&hint_num), "{name}: {hint_num}");
        let hint = store.resolve(id(hint_num)).unwrap();
        let hint = hint.as_stream().unwrap();
        assert!(hint.dict.get_int(b"S").is_some(), "{name}");
        assert!(!store.stream_data(hint).unwrap().data.is_empty(), "{name}");

        // The document reads: three pages in order, and the /Info title.
        let contents = page_contents(&store);
        assert_eq!(contents.len(), qpdf::PAGES as usize, "{name}");
        for (k, content) in (1..).zip(&contents) {
            assert_eq!(*content, qpdf::page_content(name, k), "{name} page {k}");
        }
        let info_dict = store.deref(store.trailer().get(b"Info").unwrap()).unwrap();
        assert_eq!(
            info_dict.as_dict().unwrap().get_str_bytes(b"Title"),
            Some(format!("Folioxide fixture {name}").as_bytes()),
            "{name}"
        );
        assert!(
            store.diagnostics().is_empty(),
            "{name}: {:?}",
            store.diagnostics()
        );
    }
}

#[test]
fn linearized_then_updated_keeps_its_revision_ends() {
    // An incremental update appended to a linearized file (what signing one does, ARCHITECTURE
    // trap #12): its /Prev is the final startxref (the first-page section). The two linearized
    // revisions still end where the original file did, the update ends with the new file, and
    // the original file is exactly the prefix that opens with the first two revisions.
    for info in qpdf::infos() {
        let name = info.name;
        let original = committed_qpdf(name);
        let len = original.len();
        let store = Store::open_bytes(original.clone(), &OpenOptions::default()).unwrap();
        let size = store.trailer().get_int(b"Size").unwrap();
        let root = store.root_id().unwrap();
        let prev = last_startxref(&original);
        drop(store);

        let mut updated = original.clone();
        let num = u32::try_from(size).unwrap();
        let at = updated.len();
        updated.extend_from_slice(format!("{num} 0 obj\n(appended)\nendobj\n").as_bytes());
        let xref = updated.len();
        updated.extend_from_slice(
            format!(
                "xref\n0 1\n0000000000 65535 f\r\n{num} 1\n{at:010} 00000 n\r\ntrailer\n\
                 << /Size {} /Root {} {} R /Prev {prev} >>\nstartxref\n{xref}\n%%EOF\n",
                size + 1,
                root.num,
                root.r#gen,
            )
            .as_bytes(),
        );
        let store = Store::open_bytes(updated.clone(), &options(Strictness::Strict))
            .unwrap_or_else(|err| panic!("{name}: {err}"));
        assert!(
            store.diagnostics().is_empty(),
            "{name}: {:?}",
            store.diagnostics()
        );
        let revisions = store.revisions();
        assert_eq!(revisions.len(), 3, "{name}");
        assert_eq!(revisions[2].startxref, xref as u64, "{name}");
        assert_eq!(revisions[2].xref_kind, XrefKind::Table, "{name}");
        assert_eq!(revisions[1].startxref, prev, "{name}");
        let ends: Vec<u64> = revisions.iter().map(|r| r.eof_end).collect();
        assert_eq!(
            ends,
            [len as u64, len as u64, updated.len() as u64],
            "{name}"
        );
        assert_eq!(
            store.resolve(id(num)).unwrap().as_str_bytes(),
            Some(&b"appended"[..])
        );
        assert_eq!(page_contents(&store).len(), qpdf::PAGES as usize, "{name}");
        // The prefix up to the linearized revisions' end is the original file.
        let prefix = &updated[..usize::try_from(revisions[1].eof_end).unwrap()];
        assert_eq!(prefix, &original[..], "{name}");
        let reopened = Store::open_bytes(prefix.to_vec(), &options(Strictness::Strict)).unwrap();
        assert_eq!(reopened.revisions().len(), 2, "{name}");
    }
}
